def _fmt(v):
    v = round(v, 2)
    return str(int(v)) if v == int(v) else str(v)


def parse(d):
    """Figma export(M/L/H/V/Z 절대좌표) → 서브패스별 절대 점 목록.

    좌표를 단순히 x,y 쌍으로 세면 안 된다 — H/V 는 인수가 1개라서
    이후 모든 좌표의 x/y 가 밀린다(실제로 이 버그로 TV 높이가 50.5→56 이 됐다).
    출력은 레포 관례인 **쌍 좌표 M/L/Z** 로만 재작성해 하위 도구
    (gen_notice._bbox 등)가 그대로 동작하게 한다."""
    toks = re.findall(r"[MLHVZmlhvz]|-?\d+\.?\d*", d)
    subs, pts, cur, start, cmd, i = [], [], (0.0, 0.0), (0.0, 0.0), None, 0
    while i < len(toks):
        t = toks[i]
        if re.match(r"[A-Za-z]", t):
            cmd = t
            i += 1
            if cmd in "Zz":
                if pts:
                    subs.append(pts)
                pts, cur = [], start
                continue
        C = cmd.upper()
        rel = cmd.islower()
        if C == "M":
            if pts:
                subs.append(pts)
            x, y = float(toks[i]), float(toks[i + 1]); i += 2
            cur = (cur[0] + x, cur[1] + y) if rel else (x, y)
            start = cur
            pts = [cur]
            cmd = "l" if rel else "L"
        elif C == "L":
            x, y = float(toks[i]), float(toks[i + 1]); i += 2
            cur = (cur[0] + x, cur[1] + y) if rel else (x, y)
            pts.append(cur)
        elif C == "H":
            x = float(toks[i]); i += 1
            cur = (cur[0] + x, cur[1]) if rel else (x, cur[1])
            pts.append(cur)
        elif C == "V":
            y = float(toks[i]); i += 1
            cur = (cur[0], cur[1] + y) if rel else (cur[0], y)
            pts.append(cur)
        else:
            raise SystemExit(f"지원하지 않는 커맨드: {cmd}")
    if pts:
        subs.append(pts)
    return subs


def bbox_of(subs):
    xs = [p[0] for s in subs for p in s]
    ys = [p[1] for s in subs for p in s]
    return min(xs), min(ys), max(xs), max(ys)


def emit(subs, k, dx, dy):
    out = []
    for s in subs:
        out.append(" ".join(("M" if j == 0 else "L")
                            + f"{_fmt(x * k + dx)} {_fmt(y * k + dy)}"
                            for j, (x, y) in enumerate(s)) + " Z")
    return " ".join(out)


if __name__ == "__main__":
    for name, spec in FIGMA.items():
        k = TARGET_STROKE / spec["stroke"]
        subs = parse(spec["d"])
        x0, y0, x1, y1 = bbox_of(subs)
        # export 의 bbox 가 노드 크기와 같아야 한다 — 파싱이 틀리면 여기서 걸린다
        fw, fh = spec["size"]
        assert abs((x1 - x0) - fw) < 0.6 and abs((y1 - y0) - fh) < 0.6, \
            f"{name}: 파싱 bbox {(x1-x0):.2f}×{(y1-y0):.2f} ≠ Figma {fw}×{fh}"
        w, h = (x1 - x0) * k, (y1 - y0) * k
        if max(w, h) > GRID:
            raise SystemExit(f"{name}: 100 그리드 초과 ({w:.1f}×{h:.1f})")
        dx = GRID / 2 - w / 2 - x0 * k
        dy = GRID / 2 - h / 2 - y0 * k
        d = emit(subs, k, dx, dy)
        for suffix, fill in (("", INK), ("-white", WHITE), ("-current", "currentColor")):
            out = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" '
                   f'width="100" height="100" role="img" aria-label="{spec["label"]}">\n'
                   f'  <path fill="{fill}" fill-rule="evenodd" d="{d}"/>\n</svg>\n')
            with open(os.path.join(HERE, f"picto-{name}{suffix}.svg"), "w", encoding="utf-8") as f:
                f.write(out)
        print(f"picto-{name}.svg  Figma {spec['size'][0]}×{spec['size'][1]} "
              f"(stroke {spec['stroke']:.3f}) → k {k:.4f} → 그리드 {w:.1f}×{h:.1f}")
